let managerRecords={},ledgerError='',activeSnapshot=null;
function loadDailyRecords(){try{managerRecords=DailyLedger.load()}catch(e){ledgerError='브라우저의 일일 기록을 읽지 못했습니다. 저장소 설정과 저장 데이터를 확인해주세요.';managerRecords={}}}
function resolveSnapshot(){if(state.date<=DailyLedger.SEED)return DATA.snapshots[state.store+'_'+state.date]||null;return managerRecords[state.store]?.[state.date]?.items||null;}
function selectRecordDate(ds){if(ds>$('#dateSelect').max){toast('선택 가능한 날짜 범위를 확인해주세요.');return}state.date=ds;state.overrides={};state.nav='daily';$('#dateSelect').value=ds;render();}
function renderDailyEntry(){
 const root=$('#dailyInventory'),prev=DailyLedger.previousSnapshot(DATA,managerRecords,state.store,state.date),next=DailyLedger.nextDate(managerRecords,state.store);
 if(ledgerError){root.innerHTML=`<section class="panel empty">${ledgerError}</section>`;return;}
 if(!prev){root.innerHTML=`<section class="panel gap-panel"><span class="eyebrow">RECORD REQUIRED</span><h2>이전 날짜의 재고 기록이 필요해요.</h2><p>${state.date}의 재고를 알 수 없어 과거 잔량을 현재 재고처럼 표시하지 않습니다.<br>먼저 ${next}의 실제 입고·폐기·마감 잔량을 기록해주세요.</p><button class="button primary" id="gotoNextRecord">${next} 기록하러 가기 →</button><button class="button secondary" id="gotoSeed">9월 30일 초기 재고 확인</button></section>`;$('#gotoNextRecord').onclick=()=>selectRecordDate(next);$('#gotoSeed').onclick=()=>selectRecordDate(DailyLedger.SEED);return;}
 const existing=managerRecords[state.store]?.[state.date],later=Object.keys(managerRecords[state.store]||{}).some(d=>d>state.date);
 root.innerHTML=`<div class="daily-banner"><div><span class="badge">${state.date>DailyLedger.today()?'미래 시나리오 입력':'점장 입력'}</span><b>${state.date}의 마감 재고를 기록해주세요.</b>${state.date>DailyLedger.today()?'<p class="scenario-notice">미래 날짜입니다. 입력값은 실제 관측이 아닌 테스트·계획 시나리오로 저장합니다.</p>':''}<p>${day(state.date,-1)} 마감 잔량을 이어받습니다. 새 입고는 확인한 수량만 입력하며, 입고 예정량은 자동으로 더하지 않습니다.</p></div></div><div class="entry-storage-note">이 브라우저에 저장됩니다. 다른 기기·다른 담당자와 자동 공유되지 않습니다. 수요 전망은 팀 모델의 사전 계산 결과를 사용합니다. 판매 관측은 9월 30일까지이며 현재 예측은 10월 14일 기준일까지 지원합니다.</div><section class="panel"><div class="inventory-heading"><div><div class="eyebrow">DAILY STOCK ENTRY</div><h2>실제 입고 · 폐기 · 남은 재고 입력</h2><p>아래 입력은 모두 g·ml·개 등 표시된 사용단위입니다. kg나 박스 수량을 그대로 입력하지 마세요.</p></div><button class="button secondary" id="fillPrevious">변동 없는 품목은 전일 잔량으로 채우기</button></div><div class="entry-help">입고일은 선택한 날짜로 기록합니다. 사용기한이 지난 재고는 사용할 수 없으며, 오늘 마감에 기한이 끝나는 잔량은 실제 폐기를 확인해주세요. 묶음별 잔량은 선입선출(FIFO)로 추정합니다. 입고가 빠른 묶음부터 차감하고 남은 입고일·사용기한을 확인할 수 있습니다.</div><div class="table-wrap"><table class="entry-table"><thead><tr><th>식자재 / 입력 단위</th><th>전날 마감 잔량</th><th>기한 확인 / 입고 예정</th><th>실제 입고량</th><th>실제 폐기량</th><th>마감 잔량</th></tr></thead><tbody>${[...prev].sort((a,b)=>a.ingredient_id.localeCompare(b.ingredient_id)).map(p=>{
 const a=existing?.items.find(i=>i.ingredient_id===p.ingredient_id)?.actual;
 const expired=p.lots.filter(l=>l.expiry<=state.date).reduce((sum,l)=>sum+l.qty,0),pending=p.pending.filter(x=>x.date<=state.date).reduce((s,x)=>s+x.qty,0);
 return `<tr data-entry="${p.ingredient_id}"><td><b>${escapeHTML(p.ingredient_name)}</b><small class="history-sub">입력 단위: <strong>${p.use_unit}</strong></small></td><td>${n(p.stock)} ${p.use_unit}</td><td>${expired?`<span class="badge waste">마감까지 기한 도래 ${n(expired)} ${p.use_unit}</span>`:'<span class="muted">당일 기한 도래 없음</span>'}${pending?`<small class="history-sub">미확인 예정량 ${n(pending)} ${p.use_unit} · 실제 입고 확인 필요</small>`:''}</td><td><input data-field="received" type="number" min="0" step="1" value="${a?a.received_qty:0}" aria-label="${p.ingredient_name} 실제 입고량"></td><td><input data-field="waste" type="number" min="0" step="1" value="${a?a.waste_qty:0}" aria-label="${p.ingredient_name} 실제 폐기량"><select data-field="reason" aria-label="${p.ingredient_name} 폐기 사유"><option>점장 확인 폐기</option><option>소비기한 경과</option><option>품질 이상</option><option>보관 불량</option><option>조리 실수</option></select></td><td><input data-field="closing" type="number" min="0" step="1" value="${a?a.closing_qty:''}" placeholder="실사 수량" aria-label="${p.ingredient_name} 마감 잔량" required><button class="lot-preview-button" data-track="${p.ingredient_id}">잔량·사용기한 추적 ↗</button></td></tr>`;
 }).join('')}</tbody></table></div><div class="entry-save-bar"><label><input type="checkbox" id="confirmEntry"> 실제 입고·폐기·마감 수량을 확인했습니다.</label><div id="entryError" class="entry-error" role="alert"></div><button class="button primary" id="saveDailyRecord" ${later?'disabled':''}>마감 재고 저장 · 위험 재계산</button></div></section><p class="entry-storage-note">입고일·사용기한은 실제 입고를 기준으로 유지합니다. 전날 재고 + 실제 입고 − 실제 폐기 − 마감 잔량은 ‘추정 감소량’이며, 메뉴별 판매 기록이 없으므로 판매 소진과 실사 차이를 구분하지 않습니다.${later?' 이후 기록이 있어 이 날짜는 수정할 수 없습니다.':''}</p>`;
 $$('[data-track]').forEach(button=>button.onclick=()=>{const row=button.closest('[data-entry]'),input={};row.querySelectorAll('[data-field]').forEach(el=>input[el.dataset.field]=el.value);try{const p=prev.find(i=>i.ingredient_id===button.dataset.track),result=DailyLedger.trackLots(p,state.date,input);openTrackingPreview(p,result,input);}catch(e){toast(e.message)}});
 if(later)$('#fillPrevious').disabled=true;if(existing)for(const p of existing.items){const select=$(`[data-entry="${p.ingredient_id}"] [data-field="reason"]`),reason=p.actual.waste_records[0]?.reason;if(reason)select.value=reason;}
 $('#fillPrevious').onclick=()=>{$$('[data-entry]').forEach(row=>{const field=row.querySelector('[data-field="closing"]');if(field.value==='')field.value=prev.find(p=>p.ingredient_id===row.dataset.entry).stock});toast('빈 잔량을 전일 수량으로 채웠습니다. 변동이 있는 품목과 기한 도래 품목은 수정해주세요.')};
 $('#saveDailyRecord').onclick=()=>{const error=$('#entryError');if(!$('#confirmEntry').checked){error.textContent='실제 수량 확인에 체크한 뒤 저장해주세요.';return}try{const inputs={};$$('[data-entry]').forEach(row=>{const input={};row.querySelectorAll('[data-field]').forEach(el=>input[el.dataset.field]=el.value);inputs[row.dataset.entry]=input});const record=DailyLedger.buildRecord(DATA,managerRecords,state.store,state.date,inputs);const updated=JSON.parse(JSON.stringify(managerRecords));updated[state.store]??={};updated[state.store][state.date]=record;DailyLedger.save(updated);managerRecords=updated;render();toast('마감 기록을 저장하고 위험을 다시 계산했습니다.')}catch(e){error.textContent=e.message||'저장하지 못했습니다. 브라우저 저장 공간을 확인해주세요.';error.scrollIntoView({block:'center',behavior:'smooth'})}};
}
function attachSavedActions(){const row=$('#dailyInventory .daily-next');if(!row)return;const bar=document.createElement('div');bar.className='entry-saved-actions';bar.innerHTML=`<span>점장 입력 기록 · 이 브라우저에 저장됨</span><button class="button secondary" id="editDailyRecord">입력값 수정</button><button class="button primary" id="nextDailyRecord">다음 날 기록 →</button><button class="button secondary" id="backupDailyRecords">기록 백업</button>`;row.after(bar);$('#editDailyRecord').onclick=()=>renderDailyEntry();$('#nextDailyRecord').onclick=()=>selectRecordDate(day(state.date,1));$('#backupDailyRecords').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,records:managerRecords},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='일일재고_백업.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};}
